import 'package:flutter/material.dart';import 'package:shared_preferences/shared_preferences.dart';
class PrivacyCenterPage extends StatefulWidget{const PrivacyCenterPage({super.key});@override State<PrivacyCenterPage> createState()=>_PrivacyCenterPageState();}
class _PrivacyCenterPageState extends State<PrivacyCenterPage>{bool analytics=false,careAlerts=true,biometric=false;@override void initState(){super.initState();_load();}Future<void>_load()async{final p=await SharedPreferences.getInstance();analytics=p.getBool('privacy_analytics')??false;careAlerts=p.getBool('care_alerts')??true;biometric=p.getBool('biometric_lock')??false;if(mounted)setState((){});}Future<void>set(String k,bool v)async{final p=await SharedPreferences.getInstance();await p.setBool(k,v);setState((){});}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Privacy Center')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Your health data, your choices',style:TextStyle(fontSize:25,fontWeight:FontWeight.w900)),const SizedBox(height:8),const Text('DoseBuddy keeps sharing controls explicit. These settings are stored on this device in the current prototype.',style:TextStyle(color:Colors.grey,height:1.4)),const SizedBox(height:20),Card(child:Column(children:[SwitchListTile(title:const Text('Anonymous product analytics'),subtitle:const Text('Prototype preference only. No analytics SDK is connected.'),value:analytics,onChanged:(v){analytics=v;set('privacy_analytics',v);}),SwitchListTile(title:const Text('Care Circle alerts'),subtitle:const Text('Allow caregiver-related notifications when that system is connected.'),value:careAlerts,onChanged:(v){careAlerts=v;set('care_alerts',v);}),SwitchListTile(title:const Text('App lock'),subtitle:const Text('Preference prepared for biometric authentication integration.'),value:biometric,onChanged:(v){biometric=v;set('biometric_lock',v);})])),const SizedBox(height:18),Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:const Color(0xFFF0F1F7),borderRadius:BorderRadius.circular(18)),child:const Text('Production note: cloud sync, caregiver sharing, biometrics, and analytics require secure backend/platform integrations before release. DoseBuddy should never imply those protections are active until they are actually connected.',style:TextStyle(height:1.45)))]));}
